import glob, re
for f in sorted(glob.glob("site/**/*.md", recursive=True)):
    txt = open(f).read()
    m = re.match(r"^---\s*\n(.*?)\n---\n", txt, re.S)
    if not m:
        print("NO FM:", f)
        continue
    fm = m.group(1)
    def val(k):
        for line in fm.split("\n"):
            line = line.strip()
            if line.startswith(k+":"):
                return line[len(k):].strip()
    fields = {k: val(k) for k in ["layer","series","order","title","status","date","updated","tldr"]}
    summary_words = len(txt.split("---",2)[2].split("---",1)[0].count("\n"))  # skip
    print(f, {k:v for k,v in fields.items() if v})
    # summary length check
    body = txt.split("---\n",2)
    if len(body) >= 3:
        sm = re.search(r"summary:\s*\|?\n", body[1])
