import glob, re
def parse_fm(f):
    txt = open(f).read()
    m = re.match(r"^---\s*\n(.*?)\n---\n", txt, re.S)
    if not m: return None
    d = {}
    for line in m.group(1).split("\n"):
        line = line.strip()
        if ":" in line and not line.startswith(" "):
            k, v = line.split(":", 1)
            d[k.strip()] = v.strip()
    return d

for f in sorted(glob.glob("site/**/*.md", recursive=True)):
    if "AUTHORING" in f or f.endswith("AUTHORING.md"): continue
    d = parse_fm(f)
    if d is None:
        print("NO FM:", f); continue
    missing = {k:d.get(k) for k in ["layer","title","status","updated"] if d.get(k) in (None,"")}
    if "summary" not in d and d.get("layer") != "series":
        missing["summary"] = None
    ok_status = ("experiment" in d.get("layer","") or "series" in d.get("layer","") and False)
    if d.get("layer") == "experiment":
        st = d.get("status")
        assert st in ("planned","running","done"), (f, st)
        assert "date" in d, (f, "no date")
    elif d.get("layer") == "series":
        assert d.get("status") in ("active","done"), (f, d.get("status"))
    elif d.get("layer") != "project":
        raise ValueError((f, d.get("layer")))
    if missing: print(f, "MISSING:", missing)
print("frontmatter scan done")
